390				}
391				bodies[url] = w.Body.String()
392			}
393			return bodies
394		}
395	
396		before := snapshot()
397		// An immediate repeat is byte-for-byte identical.
398		if again := snapshot(); fmt.Sprint(again) != fmt.Sprint(before) {
399			t.Fatalf("repeat read changed:\nbefore=%v\nafter=%v", before, again)
400		}
401		if err := s.Close(); err != nil {
402			t.Fatal(err)
403		}
