405		h, s = open(t)
406		defer func() { _ = s.Close() }()
407		after := snapshot()
408		for url, body := range before {
409			if after[url] != body {
410				t.Fatalf("GET %s after restart = %q, want %q", url, after[url], body)
411			}
412		}
413	}
