		t.Fatalf("list = %v next=%v", rows, body["nextCursor"])
	}
	for i, row := range rows {
		r := row.(map[string]any)
		if r["deviceId"] != "dev" || r["id"] != fmt.Sprintf("c%d", i+1) {
			t.Fatalf("row %d = %v", i, r)
		}
	}
}

